package com.vynedam.stockai.controller; import com.vynedam.stockai.model.Batch; import com.vynedam.stockai.service.BarcodeService; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1")public class BarcodeController{private final BarcodeService s;public BarcodeController(BarcodeService x){s=x;}@PostMapping("/batches/{id}/label")@PreAuthorize("hasAnyRole('SUPER_ADMIN','STORE_MANAGER','WAREHOUSE_EXECUTIVE')")Map<String,Object>label(@PathVariable String id){return s.label(id);}@GetMapping("/scan/{code}")Batch scan(@PathVariable String code){return s.scan(code);}}
